function AutoClose() {
  const [open, setOpen] = useState(false);

  return (
    <div className="flex flex-wrap gap-2">
      <Dropdown>
        <Dropdown.Trigger asChild>
          <Button variant="outline" color="secondary" className="dropdown-toggle">
            Default
          </Button>
        </Dropdown.Trigger>
        <Dropdown.Content className="min-w-48">
          <Dropdown.Item>Menu item</Dropdown.Item>
          <Dropdown.Item>Menu item</Dropdown.Item>
          <Dropdown.Item>Menu item</Dropdown.Item>
        </Dropdown.Content>
      </Dropdown>

      <Dropdown>
        <Dropdown.Trigger asChild>
          <Button variant="outline" color="secondary" className="dropdown-toggle">
            Stays open on select
          </Button>
        </Dropdown.Trigger>
        <Dropdown.Content className="min-w-48">
          {[1, 2, 3].map((item) => (
            <Dropdown.Item key={item} onSelect={(event) => event.preventDefault()}>
              Menu item
            </Dropdown.Item>
          ))}
        </Dropdown.Content>
      </Dropdown>

      <Dropdown open={open} onOpenChange={setOpen}>
        <Dropdown.Trigger asChild>
          <Button variant="outline" color="secondary" className="dropdown-toggle">
            Manual close
          </Button>
        </Dropdown.Trigger>
        <Dropdown.Content
          className="min-w-48"
          onInteractOutside={(event) => event.preventDefault()}
          onEscapeKeyDown={(event) => event.preventDefault()}
        >
          <Dropdown.Item onSelect={(event) => event.preventDefault()}>
            Menu item
          </Dropdown.Item>
          <Dropdown.Item onSelect={(event) => event.preventDefault()}>
            Menu item
          </Dropdown.Item>
          <Dropdown.Separator />
          <Dropdown.Item onSelect={() => setOpen(false)}>Close menu</Dropdown.Item>
        </Dropdown.Content>
      </Dropdown>
    </div>
  );
}
