<div className="flex flex-wrap gap-2">
  <Drawer direction="right">
    <Drawer.Trigger asChild>
      <Button color="primary">Backdrop (default)</Button>
    </Drawer.Trigger>
    <Drawer.Content>
      <Drawer.Header>
        <Drawer.Title>Drawer</Drawer.Title>
        <Drawer.Close asChild>
          <CloseButton />
        </Drawer.Close>
      </Drawer.Header>
      <Drawer.Body>
        <Drawer.Description>
          The backdrop dims the page and scrolling is locked while the drawer is
          open.
        </Drawer.Description>
      </Drawer.Body>
    </Drawer.Content>
  </Drawer>

  <Drawer direction="right">
    <Drawer.Trigger asChild>
      <Button color="primary">No backdrop</Button>
    </Drawer.Trigger>
    <Drawer.Content overlay={false}>
      <Drawer.Header>
        <Drawer.Title>Drawer</Drawer.Title>
        <Drawer.Close asChild>
          <CloseButton />
        </Drawer.Close>
      </Drawer.Header>
      <Drawer.Body>
        <Drawer.Description>
          {'overlay={false}'} hides the backdrop so the page behind stays
          visible.
        </Drawer.Description>
      </Drawer.Body>
    </Drawer.Content>
  </Drawer>

  <Drawer direction="right" modal={false}>
    <Drawer.Trigger asChild>
      <Button color="primary">Body scrolling</Button>
    </Drawer.Trigger>
    <Drawer.Content overlay={false}>
      <Drawer.Header>
        <Drawer.Title>Drawer</Drawer.Title>
        <Drawer.Close asChild>
          <CloseButton />
        </Drawer.Close>
      </Drawer.Header>
      <Drawer.Body>
        <Drawer.Description>
          {'modal={false}'} leaves the rest of the page scrollable and clickable.
        </Drawer.Description>
      </Drawer.Body>
    </Drawer.Content>
  </Drawer>
</div>
